function createStrategy() {
  "use strict";
  var COSTS = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var BASE_DAMAGE = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var SPLASH = { cannon: 90, flak: 70 };
  var THREAT = { grunt: 1, runner: 1, wisp: 1.4, brute: 2.6, splitter: 1.6, mender: 1.8, splitling: 0.8 };
  var BUILD = [
    [5, "cannon"], [3, "cannon"], [14, "flak"], [9, "cannon"], [8, "cannon"],
    [12, "flak"], [2, "cannon"], [13, "cannon"], [1, "cannon"], [11, "cannon"],
    [10, "flak"], [7, "cannon"], [4, "flak"], [0, "flak"], [6, "cannon"], [15, "bolt"]
  ];
  var UPGRADE = [3, 1, 6, 9, 2, 7, 14, 15, 12, 13, 11, 8, 10, 0, 5, 4];

  function tierDamage(type, tier) {
    var d = BASE_DAMAGE[type];
    for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10);
    return d;
  }

  function plan(state) {
    var actions = [];
    var gold = state.gold;
    var order = [];
    for (var i = 0; i < BUILD.length; i++) {
      order.push({ kind: "build", slot: BUILD[i][0], type: BUILD[i][1] });
      if (i + 1 === 14) {
        for (var j = 0; j < 2; j++) order.push({ kind: "upgrade", slot: UPGRADE[j] });
      }
    }
    for (var u = 0; u < UPGRADE.length; u++) order.push({ kind: "upgrade", slot: UPGRADE[u] });

    for (var a = 0; a < order.length && actions.length < 32; a++) {
      var step = order[a];
      var slotView = state.slots[step.slot];
      if (!slotView) continue;
      if (step.kind === "build") {
        var cost = COSTS[step.type];
        if (!slotView.turret && gold >= cost) {
          actions.push({ op: "build", slot: step.slot, type: step.type });
          gold -= cost;
        }
      } else {
        var turret = slotView.turret;
        if (!turret || turret.tier >= 3) continue;
        var upgradeCost = COSTS[turret.type] * (turret.tier === 1 ? 1 : 2);
        if (gold >= upgradeCost) {
          actions.push({ op: "upgrade", slot: step.slot });
          gold -= upgradeCost;
        }
      }
    }
    return actions;
  }

  function target(turret, candidates) {
    var type = turret.type;
    if (type === "cannon" || type === "flak") {
      var isCannon = type === "cannon";
      var dmg = tierDamage(type, turret.tier);
      var radius = SPLASH[type];
      var radius2 = radius * radius;
      var tie = isCannon ? 1 : 1;
      var menderWeight = isCannon ? 32 : 16;
      var best = candidates[0];
      var bestValue = -Infinity;
      for (var i = 0; i < candidates.length; i++) {
        var center = candidates[i];
        var value = 0;
        for (var j = 0; j < candidates.length; j++) {
          var other = candidates[j];
          var dx = other.x - center.x;
          var dy = other.y - center.y;
          if (dx * dx + dy * dy > radius2) continue;
          var effective = Math.max(1, dmg - other.armor);
          var amount = Math.min(other.hp, effective);
          var weight = THREAT[other.type];
          if (other.type === "mender") weight *= menderWeight;
          else if (other.type === "splitter") weight *= 2;
          else if (other.type === "brute") weight *= 1;
          else if (other.type === "wisp") weight *= 0.5;
          value += amount * weight;
        }
        var score = value - center.remaining * tie;
        if (score > bestValue) { bestValue = score; best = center; }
      }
      return best.id;
    }

    if (type === "lance") {
      var lb = candidates[0];
      var lv = Infinity;
      for (var k = 0; k < candidates.length; k++) {
        var e = candidates[k];
        var score2 = e.hp + e.remaining * 10;
        if (e.type === "mender") score2 -= 0;
        if (e.type === "brute") score2 -= 0;
        if (score2 < lv) { lv = score2; lb = e; }
      }
      return lb.id;
    }

    var boltBest = candidates[0];
    var boltValue = -Infinity;
    for (var b = 0; b < candidates.length; b++) {
      var c = candidates[b];
      var v = c.speed * 75 - c.remaining;
      if (c.type === "mender") v += 5000;
      if (v > boltValue) { boltValue = v; boltBest = c; }
    }
    return boltBest.id;
  }

  return { plan: plan, target: target };
}

