  var dx = 0, dz = 0;
  if (bEnemy) { dx = bEnemy.x - aEnemy.x; dz = bEnemy.y - aEnemy.y; }
  if (dx * dx + dz * dz < 0.0001) {
    var prev = snapshotAt(tick - 1);
    if (prev) {
