const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 650 }, deviceScaleFactor: 1 });
  const errors = [];
  const logs = [];
  page.on('console', m => logs.push(m.type() + ': ' + m.text()));
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  page.on('requestfailed', r => errors.push('REQFAIL: ' + r.url() + ' ' + (r.failure() && r.failure().errorText)));
  const file = 'file://' + path.resolve('index.html');
  await page.goto(file, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(1500);
  const state = await page.evaluate(() => ({
    hasThree: typeof THREE !== 'undefined',
    report: window.BENCH_REPORT,
    countdown: document.getElementById('countdown').textContent,
    countdownDisplay: getComputedStyle(document.getElementById('countdown')).display,
    scrub: document.getElementById('scrubber').value,
    canvasSize: [document.getElementById('stage').width, document.getElementById('stage').height],
    modeGuess: document.getElementById('btn-toggle').getAttribute('aria-label')
  }));
  console.log('STATE1', JSON.stringify(state, null, 2));
  await page.screenshot({ path: '.dev/shot1.png' });
  await page.waitForTimeout(3200);
  const state2 = await page.evaluate(() => ({
    countdown: document.getElementById('countdown').textContent,
    countdownDisplay: getComputedStyle(document.getElementById('countdown')).display,
    scrub: document.getElementById('scrubber').value,
    aria: document.getElementById('btn-toggle').getAttribute('aria-label'),
    filter: document.getElementById('stage').style.filter,
    report: window.BENCH_REPORT
  }));
  console.log('STATE2', JSON.stringify(state2, null, 2));
  await page.screenshot({ path: '.dev/shot2.png' });
  console.log('LOGS', logs.slice(0, 30).join('\n'));
  console.log('ERRORS', errors.join('\n'));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

