const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 650 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  await page.waitForTimeout(1000);
  async function seek(t, name) {
    await page.evaluate((v) => {
      const s = document.getElementById('scrubber');
      s.value = String(v);
      s.dispatchEvent(new Event('input', { bubbles: true }));
    }, t);
    await page.waitForTimeout(600);
    await page.screenshot({ path: '.dev/' + name + '.png' });
    const info = await page.evaluate(() => ({
      aria: document.getElementById('btn-toggle').getAttribute('aria-label'),
      scrub: document.getElementById('scrubber').value,
      countdown: document.getElementById('countdown').textContent,
      filter: document.getElementById('stage').style.filter,
      report: { fps: window.BENCH_REPORT.measuredFps }
    }));
    console.log(name, JSON.stringify(info));
  }
  await seek(20, 't20');
  await seek(40, 't40');
  await seek(70, 't80');
  await seek(92.4, 't924');
  await seek(92.6, 't926');
  await seek(100, 't100');
  console.log('ERRORS', errors.join('\n'));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

