const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 650 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
  const get = () => page.evaluate(() => ({
    cdText: document.getElementById('countdown').textContent,
    cdDisplay: getComputedStyle(document.getElementById('countdown')).display,
    scrub: document.getElementById('scrubber').value,
    aria: document.getElementById('btn-toggle').getAttribute('aria-label'),
    pauseDisp: getComputedStyle(document.getElementById('icon-pause')).display,
    playDisp: getComputedStyle(document.getElementById('icon-play')).display,
    active: [...document.querySelectorAll('.speed-pill')].map(x => x.getAttribute('aria-checked')).join(','),
    filter: document.getElementById('stage').style.filter
  }));
  console.log('t~150', await get());
  await page.waitForTimeout(700);
  console.log('t~850', await get());
  await page.click('#btn-toggle');
  console.log('after pause during countdown', await get());
  await page.waitForTimeout(300);
  console.log('paused stable', await get());
  // Set speed 2x then refire, check speed persistence and no countdown during hold
  await page.click('.speed-pill[data-speed="2.0"]');
  console.log('speed 2x', await get());
  await page.click('#btn-refire');
  console.log('refire immediate', await get());
  await page.waitForTimeout(450);
  console.log('refire 450ms', await get());
  await page.waitForTimeout(700);
  console.log('refire 1150ms', await get());
  await page.waitForTimeout(400);
  console.log('playing after hold', await get());
  // scrub to 99.8, should pause
  await page.evaluate(() => { const s = document.getElementById('scrubber'); s.value = '99.800'; s.dispatchEvent(new Event('input', { bubbles: true })); });
  await page.waitForTimeout(150);
  console.log('after scrub', await get());
  // play to end
  await page.click('#btn-toggle');
  await page.waitForTimeout(700);
  console.log('after end', await get());
  await page.click('#btn-toggle');
  await page.waitForTimeout(300);
  console.log('after replay from ended', await get());
  // scrub during countdown
  await page.click('#btn-refire');
  await page.evaluate(() => { const s = document.getElementById('scrubber'); s.value = '12.345'; s.dispatchEvent(new Event('input', { bubbles: true })); });
  console.log('scrub during refire', await get());
  // click toggle play at end? restore and test
  await page.waitForTimeout(300);
  console.log('ERRORS', errors.join('\n'));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

