    aria: document.getElementById('btn-toggle').getAttribute('aria-label')
  }));
  console.log(JSON.stringify(info, null, 2));
  await page.screenshot({ path: '.dev/wide.png' });
  // deterministic scrub checks
  async function seek(t) {
    await page.evaluate((v) => { const s = document.getElementById('scrubber'); s.value = String(v); s.dispatchEvent(new Event('input', { bubbles: true })); }, t);
    await page.waitForTimeout(250);
    return page.screenshot({ path: null });
  }
  const a = await seek(40);
  await seek(75);
  const b = await seek(40);
  const c = await seek(40);
  console.log('hashA', crypto.createHash('sha256').update(a).digest('hex'));
  console.log('hashB', crypto.createHash('sha256').update(b).digest('hex'));
  console.log('hashC', crypto.createHash('sha256').update(c).digest('hex'));
  console.log('ERRORS', errors.join('\n'));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

