const genotype = {"builds":[{"slot":5,"type":"cannon"},{"slot":3,"type":"cannon"},{"slot":14,"type":"flak"},{"slot":9,"type":"cannon"},{"slot":8,"type":"cannon"},{"slot":12,"type":"flak"},{"slot":2,"type":"cannon"},{"slot":13,"type":"cannon"},{"slot":1,"type":"cannon"},{"slot":11,"type":"cannon"},{"slot":10,"type":"flak"},{"slot":7,"type":"cannon"},{"slot":4,"type":"flak"},{"slot":0,"type":"flak"},{"slot":6,"type":"cannon"},{"slot":15,"type":"bolt"}],"upOrder":[3,1,6,9,2,7,14,15,12,13,11,8,10,0,5,4],"earlyN":14,"earlyUpN":2};
const BASE_DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
const SPLASH = { cannon: 90, flak: 70 };
const THREAT = { grunt: 1, runner: 1, wisp: 1.4, brute: 2.6, splitter: 1.6, mender: 1.8, splitling: .8 };
function tierDmg(type, tier) { let d = BASE_DMG[type]; for (let i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
function makeStrategy(tgt) { const g=genotype,builds=g.builds,upOrder=g.upOrder; return () => ({ plan(s) { const acts=[];let gold=s.gold;const order=[];for(let i=0;i<builds.length;i++){order.push({kind:'build',b:builds[i]});if(i+1===g.earlyN)for(let j=0;j<g.earlyUpN;j++)order.push({kind:'up',slot:upOrder[j%upOrder.length]});}for(const slot of upOrder)order.push({kind:'up',slot});for(const a of order){if(a.kind==='build'){const sl=s.slots[a.b.slot];if(sl&&!sl.turret&&gold>=COSTS[a.b.type]){acts.push({op:'build',slot:a.b.slot,type:a.b.type});gold-=COSTS[a.b.type];}}else{const sl=s.slots[a.slot];if(!sl||!sl.turret||sl.turret.tier>=3)continue;const cost=COSTS[sl.turret.type]*(sl.turret.tier===1?1:2);if(gold>=cost){acts.push({op:'upgrade',slot:a.slot});gold-=cost;}}}return acts;},target:tgt}); }
function evalT(tgt,seedList=train){const st=makeStrategy(tgt);let sum=0;for(const s of seedList)sum+=rampartSimulate(st,s,12020).score;return sum/seedList.length;}
function splashTarget(t,c,p){
  const tt=t.type,dmg=tierDmg(tt,t.tier),r2=SPLASH[tt]**2;
  const mw=tt==='cannon'?p.cannonMender:p.flakMender;
  let b=c[0],bv=-Infinity;
  for(const e of c){
    let val=0;
    for(const o of c){
      const dx=o.x-e.x,dy=o.y-e.y;if(dx*dx+dy*dy>r2)continue;
      const eff=Math.max(1,dmg-o.armor);let d=Math.min(o.hp,eff);
      let w=THREAT[o.type];if(o.type==='mender')w*=mw;else if(o.type==='splitter')w*=p.splitter;else if(o.type==='brute')w*=p.brute;else if(o.type==='wisp')w*=p.wisp;
      if(p.victimUrg>0)w*=1+p.victimUrg/(o.remaining+300);
      val+=d*w;
    }
    let score=val;
    if(p.centerUrg>0) score*=1+p.centerUrg/(e.remaining+300);
    score-=e.remaining*p.tie;
    if(p.flakNearest && tt==='flak') score=-e.remaining;
    if(score>bv){bv=score;b=e;}
  }
  return b.id;
}
function targetWith(p){return (t,c)=>{if(t.type==='cannon'||t.type==='flak')return splashTarget(t,c,p);if(t.type==='lance'){let b=c[0],bv=Infinity;for(const e of c){const v=e.hp+e.remaining*10;if(v<bv){bv=v;b=e;}}return b.id;}let b=c[0],bv=-Infinity;for(const e of c){let v=e.speed*75-e.remaining;if(e.type==='mender')v+=5000;if(v>bv){bv=v;b=e;}}return b.id;};}
const base={cannonMender:32,flakMender:16,splitter:2,brute:1,wisp:.5,tie:1,victimUrg:0,centerUrg:0,flakNearest:false};
console.log('base',evalT(targetWith(base)).toFixed(3));
let best={p:{...base},score:evalT(targetWith(base))};
const grids=[
 ['cannonMender',[8,16,24,32,48,64]],
 ['flakMender',[8,16,24,32]],
 ['splitter',[1,2,3,4]],
 ['brute',[0.5,1,1.5,2]],
 ['wisp',[0.25,.5,.8,1]],
 ['tie',[0,.3,1,3,10]],
 ['centerUrg',[0,100,300,1000,3000,10000]],
 ['victimUrg',[0,100,300,1000,3000]],
 ['flakNearest',[false,true]]
];
for(let iter=0;iter<3;iter++){
 let improved=false;
 for(const [key,vals] of grids){
  let bv=best.p[key],bs=best.score;
  for(const v of vals){const p={...best.p,[key]:v};const sc=evalT(targetWith(p));if(sc>bs+1e-9){bs=sc;bv=v;}}
  if(bv!==best.p[key]){best.p[key]=bv;best.score=bs;improved=true;}
  console.log('iter',iter,key,best.p[key],best.score.toFixed(3));
 }
 if(!improved)break;
}
console.log('best',JSON.stringify(best.p),'train',best.score.toFixed(3),'all',evalT(targetWith(best.p),seeds).toFixed(3));
console.log(seeds.map(s=>rampartSimulate(makeStrategy(targetWith(best.p)),s,12020).score.toFixed(1)).join(','));

